#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <sstream>

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::istringstream iss(line);
    std::vector<int> arr;
    int num;
    while (iss >> num) {
        arr.push_back(num);
    }
    int min_val = std::min(arr[1], arr[2]);
    std::string s = (arr[0] <= min_val) ? "Yes" : "No";
    std::cout << s << std::endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <string>

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::vector<int> arr;
    size_t start = 0;
    size_t end = line.find(' ');
    while (end != std::string::npos) {
        arr.push_back(std::stoi(line.substr(start, end - start)));
        start = end + 1;
        end = line.find(' ', start);
    }
    arr.push_back(std::stoi(line.substr(start)));
    int min_val = std::min(arr[1], arr[2]);
    std::string s = (arr[0] <= min_val) ? "Yes" : "No";
    std::cout << s << std::endl;
    return 0;
}

