    std::getline(std::cin, line);
    std::vector<int> arr;
    size_t pos = 0;
    while ((pos = line.find(' ')) != std::string::npos) {
        arr.push_back(std::stoi(line.substr(0, pos)));
        line.erase(0, pos + 1);
